package ai.eva.android.probe;
import android.content.*;import android.net.*;import android.os.*;import android.webkit.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Private loopback transport to this app's WebView DevTools socket and native tab host. */
final class DesktopBrowserHost {
 static DesktopBrowserHost instance; final Context context;final ServerSocket server;final String token=UUID.randomUUID().toString();
 final ExecutorService workers=Executors.newCachedThreadPool();final LinkedHashMap<String,WebView> tabs=new LinkedHashMap<>();String active="";final Map<WebView,BrowserTransfers> transfers=new HashMap<>();final Map<WebView,BrowserSitePermissions> permissions=new HashMap<>();
 static synchronized DesktopBrowserHost get(Context c)throws Exception{if(instance==null)instance=new DesktopBrowserHost(c.getApplicationContext());return instance;}
 DesktopBrowserHost(Context c)throws Exception{context=c;server=new ServerSocket(0,32,InetAddress.getByName("127.0.0.1"));workers.execute(()->{while(!server.isClosed())try{Socket s=server.accept();workers.execute(()->serve(s));}catch(Exception ignored){}});}
 String endpoint(){return "http://127.0.0.1:"+server.getLocalPort()+"/"+token;}
 void register(WebView view,BrowserWindow b){if(tabs.containsValue(view))return;String id=UUID.randomUUID().toString();tabs.put(id,view);active=id;if(b!=null){transfers.put(view,b.transfers);permissions.put(view,b.sitePermissions);}tag(view,id);if(androidx.webkit.WebViewFeature.isFeatureSupported(androidx.webkit.WebViewFeature.DOCUMENT_START_SCRIPT))androidx.webkit.WebViewCompat.addDocumentStartJavaScript(view,"window.__evaNativeTab="+JSONObject.quote(id),Collections.singleton("*"));}
 void tag(WebView view,String id){view.evaluateJavascript("window.__evaNativeTab="+JSONObject.quote(id),null);}
 void tagCurrent(WebView view){for(Map.Entry<String,WebView> e:tabs.entrySet())if(e.getValue()==view){tag(view,e.getKey());break;}}
 static String line(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();int n;while((n=in.read())!=-1){if(n==10)break;if(n!=13)b.write(n);if(b.size()>16384)throw new IOException("Header too large");}return b.toString("UTF-8");}
 static byte[] readBody(InputStream in,int size)throws IOException{byte[] body=new byte[size];int offset=0;while(offset<size){int count=in.read(body,offset,size-offset);if(count<0)throw new EOFException("Incomplete request body");offset+=count;}return body;}
 static void copy(InputStream in,OutputStream out)throws IOException{byte[] buffer=new byte[16384];int count;while((count=in.read(buffer))!=-1){out.write(buffer,0,count);out.flush();}}
 void serve(Socket socket){try(Socket s=socket){s.setSoTimeout(65000);InputStream in=s.getInputStream();String request=line(in);String[] parts=request.split(" ");if(parts.length!=3) return;String prefix="/"+token;if(!parts[1].startsWith(prefix+"/")){reply(s,403,"{}");return;}String path=parts[1].substring(prefix.length());List<String> headers=new ArrayList<>();int size=0;String h;while(!(h=line(in)).isEmpty()){headers.add(h);if(h.toLowerCase(Locale.ROOT).startsWith("content-length:"))size=Integer.parseInt(h.substring(15).trim());}if(size<0||size>8*1024*1024)throw new IOException("Body too large");
 if(path.equals("/host")){byte[] body=readBody(in,size);JSONObject args=body.length==0?new JSONObject():new JSONObject(new String(body,StandardCharsets.UTF_8));CompletableFuture<JSONObject> f=new CompletableFuture<>();new Handler(Looper.getMainLooper()).post(()->{try{f.complete(host(args));}catch(Exception e){f.completeExceptionally(e);}});try{reply(s,200,f.get(30,TimeUnit.SECONDS).toString());}catch(Exception e){reply(s,500,new JSONObject().put("error",String.valueOf(e.getCause()==null?e:e.getCause())).toString());}return;}
 try(LocalSocket local=new LocalSocket()){local.connect(new LocalSocketAddress("webview_devtools_remote_"+android.os.Process.myPid(),LocalSocketAddress.Namespace.ABSTRACT));OutputStream out=local.getOutputStream();out.write((parts[0]+" "+path+" HTTP/1.1\r\n").getBytes(StandardCharsets.UTF_8));for(String header:headers)out.write((header+"\r\n").getBytes(StandardCharsets.UTF_8));out.write("\r\n".getBytes(StandardCharsets.UTF_8));out.flush();Future<?> sending=workers.submit(()->{try{copy(in,local.getOutputStream());}catch(Exception ignored){}});try{copy(local.getInputStream(),s.getOutputStream());}finally{sending.cancel(true);}}
 }catch(Exception ignored){}}
 static byte[] read(InputStream in,int size)throws IOException{byte[] b=new byte[size];new DataInputStream(in).readFully(b);return b;}
 static void pump(InputStream in,OutputStream out)throws IOException{byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){out.write(b,0,n);out.flush();}}
 static void reply(Socket s,int code,String body)throws IOException{byte[] bytes=body.getBytes(StandardCharsets.UTF_8);OutputStream out=s.getOutputStream();out.write(("HTTP/1.1 "+code+" OK\r\nContent-Type: application/json\r\nContent-Length: "+bytes.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.UTF_8));out.write(bytes);out.flush();}
 void showTabs(BrowserWindow b){BrowserOwnership.userTakeover(b,"你已管理标签页");List<String> ids=new ArrayList<>(tabs.keySet());String[] titles=new String[ids.size()];for(int i=0;i<ids.size();i++){WebView v=tabs.get(ids.get(i));titles[i]=(ids.get(i).equals(active)?"● ":"")+(v.getTitle()==null?"新标签":v.getTitle());}new android.app.AlertDialog.Builder(b.getContext()).setTitle("标签页").setItems(titles,(d,n)->{try{host(new JSONObject().put("action","activate").put("id",ids.get(n)));}catch(Exception e){b.status(e.getMessage());}}).setPositiveButton("新标签",(d,n)->{try{host(new JSONObject().put("action","create"));}catch(Exception e){b.status(e.getMessage());}}).setNeutralButton("关闭当前标签",(d,n)->{try{host(new JSONObject().put("action","close").put("id",active));}catch(Exception e){b.status(e.getMessage());}}).setNegativeButton("返回",null).show();}
 void closed(){for(WebView view:new ArrayList<>(tabs.values())){if(view!=BrowserWindow.live.browser){BrowserTransfers t=transfers.get(view);if(t!=null)t.close();view.destroy();}}tabs.clear();transfers.clear();permissions.clear();active="";}
 JSONObject host(JSONObject a)throws Exception{BrowserWindow b=BrowserWindow.live;if(b==null)throw new IOException("请先打开 Eva 浏览器");String action=a.optString("action","state"),id=a.optString("id");if(action.equals("screenshot")){WebView v=tabs.get(id);if(v==null)throw new IOException("标签已关闭");int w=v.getWidth(),h=v.getHeight();if(w<=0||h<=0)throw new IOException("网页尚未布局");android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(w,h,android.graphics.Bitmap.Config.ARGB_8888);try{v.draw(new android.graphics.Canvas(image));String relative="analysis/browser-shots/android-"+System.currentTimeMillis()+".png";File file=WorkspaceFiles.resolve(b.host,relative);file.getParentFile().mkdirs();try(OutputStream out=new FileOutputStream(file)){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}return new JSONObject().put("path","/root/eva-workspace/"+relative).put("fullPage",false).put("capture","native-viewport");}finally{image.recycle();}}if(action.equals("downloads")){org.json.JSONArray list=new org.json.JSONArray();BrowserTransfers t=transfers.get(tabs.get(id));if(t!=null)for(BrowserTransfers.Transfer item:t.items)list.put(new JSONObject().put("url",item.url).put("state",item.state).put("path",item.path).put("received",item.received).put("error",item.error));return new JSONObject().put("downloads",list);}
 if(action.equals("create")){WebView previous=b.browser; // Configure through the shared native setup.
 b.browser=null;b.browse();register(b.browser,b);b.browser.loadUrl("about:blank#eva-"+active);if(previous.getParent()!=null)((android.view.ViewGroup)previous.getParent()).removeView(previous);}
 if(action.equals("activate")||action.equals("close")){WebView selected=tabs.get(id);if(selected==null)throw new IOException("标签已关闭");if(action.equals("close")){tabs.remove(id);BrowserTransfers t=transfers.remove(selected);if(t!=null)t.close();permissions.remove(selected);if(selected.getParent()!=null)((android.view.ViewGroup)selected.getParent()).removeView(selected);selected.destroy();if(tabs.isEmpty()){b.browser=null;b.browse();register(b.browser,b);}else{active=tabs.keySet().iterator().next();b.browser=tabs.get(active);b.transfers=transfers.get(b.browser);b.sitePermissions=permissions.get(b.browser);b.browse();}}else{active=id;b.browser=selected;b.transfers=transfers.get(selected);b.sitePermissions=permissions.get(selected);b.browse();}b.windowMode(false,false);}
 JSONArray rows=new JSONArray();for(Map.Entry<String,WebView> e:tabs.entrySet()){WebView v=e.getValue();rows.put(new JSONObject().put("id",e.getKey()).put("url",v.getUrl()).put("title",v.getTitle()));}return new JSONObject().put("tabs",rows).put("active",active);}
}
